import{_ as o,a0 as C,w as p,s as u,ao as n,I as i,x as l,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"CI/CD 管道是什麼？ | LCTT x X-CMD","titleTemplate":false,"description":"CI/CD 管道是什麼？ | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CI/CD 管道是什麼？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CI/CD 管道是什麼？ | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210614 What is a CI-CD pipeline","title":"CI/CD 管道是什麼？","tag":"202107","desc":""},"relativePath":"202107/20210614 What is a CI-CD pipeline.md","filePath":"[post].md"}'),a={name:"202107/20210614 What is a CI-CD pipeline.md"};function d(D,t,m,I,f,b){const e=C("Link");return p(),u("div",null,[t[28]||(t[28]=n('<h1 id="ci-cd-管道是什麼" tabindex="-1">CI/CD 管道是什麼？ <a class="header-anchor" href="#ci-cd-管道是什麼" aria-label="Permalink to “CI/CD 管道是什麼？”">​</a></h1><blockquote><p>你如何定義持續集成/持續部署管道取決於你組織的要求。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/plumbing_pipes_tutorial_how_behind_scenes.png?itok=F2Z8OJV1" alt="Plumbing tubes in many directions" title="Plumbing tubes in many directions"></p><p><ruby>持續集成<rt>continuous integration</rt></ruby>/<ruby>持續部署<rt>continuous deployment</rt></ruby>（CI/CD）管道是每個 DevOps 計劃的基礎。 CI/CD 管道打破了傳統的開發孤島，使開發和運營團隊能夠在整個軟件開發生命週期中進行協作。</p>',4)),i("p",null,[t[1]||(t[1]=l("更好的是，轉向 DevOps 和 CI/CD 管道可以幫助你的組織以更高的速度更安全地 ",-1)),r(e,{href:"https://techbeacon.com/devops/5-reasons-why-cicd-vital-your-organizations-value-stream"},{default:s(()=>[...t[0]||(t[0]=[l("交付軟件",-1)])]),_:1}),t[2]||(t[2]=l("。",-1))]),t[29]||(t[29]=n('<h3 id="拆解-ci-cd-管道" tabindex="-1">拆解 CI/CD 管道 <a class="header-anchor" href="#拆解-ci-cd-管道" aria-label="Permalink to “拆解 CI/CD 管道”">​</a></h3><p>CI/CD 管道有很多定義，所以我總是建議組織定義自己的 CI/CD 管道版本和其他 DevOps 概念，而不是使用其他人的。開源 CI/CD 工具為你提供構建滿足組織要求的 CI/CD 管道的自由和選擇。</p><p>形成 CI/CD 管道的階段是將不同的任務子集分組為 <em>管道階段</em>。典型的管道階段包括：</p><ul><li><strong>構建</strong>：開發人員編譯應用程序代碼。</li><li><strong>測試</strong>：質量保證（QA）團隊使用自動化測試工具和策略測試應用程序代碼。</li><li><strong>發佈</strong>：開發團隊將應用程序代碼交付到代碼庫。</li><li><strong>部署</strong>：DevOps 團隊將應用程序代碼分階段投入生產。</li><li><strong>安全性和合規性</strong>：QA 團隊根據項目要求驗證構建。這是組織部署容器掃描工具的階段，這些工具根據<ruby>常見漏洞和暴露<rt>Common Vulnerabilities and Exposures</rt></ruby>（CVE）檢查容器鏡像的質量。</li></ul><p>這些是 CI/CD 管道的標準階段，但一些組織調整 CI/CD 管道模型以滿足他們的要求。例如，為醫療保健市場構建應用程序的組織，具有嚴格的合規性標準，可以在整個工具鏈中分發測試、驗證和合規性門檻。</p>',5)),i("p",null,[t[5]||(t[5]=l("其他示例可能是依賴於具有開源軟件（OSS）的複雜軟件供應鏈的組織。商業組件可能會設立一個門檻，開發團隊成員可以在其中為 OSS 包生成 ",-1)),i("ruby",null,[r(e,{href:"https://www.ntia.gov/SBOM"},{default:s(()=>[...t[3]||(t[3]=[l("軟件物料清單",-1)])]),_:1}),t[4]||(t[4]=i("rt",null,"software bill of materials",-1))]),t[6]||(t[6]=l("（SBOM），或者外部商業軟件供應商必須將 SBOM 作為其合同可交付成果的一部分進行交付。",-1))]),t[30]||(t[30]=n('<h3 id="ci-cd-管道的障礙" tabindex="-1">CI/CD 管道的障礙 <a class="header-anchor" href="#ci-cd-管道的障礙" aria-label="Permalink to “CI/CD 管道的障礙”">​</a></h3><p>實施 CI/CD 管道會改變團隊的流程和文化。儘管許多開發人員願意接受某些任務和測試的自動化，但人員可能成為採用 CI/CD 的障礙。</p><p>從瀑布式流程轉向 CI/CD 可能會動搖某些組織中基本的和隱含的權力結構。由於 CI/CD 管道提高了軟件交付速度，舊手動流程的“守門人”可能會受到這種變化的威脅。</p><h3 id="整合機會" tabindex="-1">整合機會 <a class="header-anchor" href="#整合機會" aria-label="Permalink to “整合機會”">​</a></h3><p>隨着你在文化、流程和工具中達到更高的 DevOps 成熟度水平，包含 CI/CD 工具鏈的工具的開源根源為一些激動人心的集成創造了機會。</p><p>分析公司 Forrester 在 2020 年預測，<ruby>即時學習<rt>just-in-time learning</rt></ruby>將加入 CI/CD 管道。如果你考慮一下，會發現這是有道理的。在當前遠程工作的時代，甚至對於新員工的遠程入職，這更有意義。例如，組織可以將文檔 wiki 與內部流程文檔集成到其管道中。</p>',6)),i("p",null,[t[8]||(t[8]=l("更雄心勃勃的組織可以將學習管理系統（LMS）（例如 ",-1)),r(e,{href:"https://moodle.org/"},{default:s(()=>[...t[7]||(t[7]=[l("Moodle",-1)])]),_:1}),t[9]||(t[9]=l("）集成到其 CI/CD 管道中。它可以使用 LMS 發佈有關新 DevOps 工具鏈功能的簡短視頻，開發人員在加入時或在整個管道中更新工具時需要學習這些功能。",-1))]),i("p",null,[t[11]||(t[11]=l("一些組織正在將羣聊和其他協作工具直接集成到他們的 CI/CD 管道中。聊天平台提供警報並支持團隊之間的協作和溝通。將 Mattermost、Rocket.Chat 或其他 ",-1)),r(e,{href:"https://opensource.com/alternatives/slack"},{default:s(()=>[...t[10]||(t[10]=[l("企業聊天",-1)])]),_:1}),t[12]||(t[12]=l(" 平台集成到你的 CI/CD 管道中需要預先規劃和分析，以確保管道用户不會被警報淹沒。",-1))]),t[31]||(t[31]=i("p",null,"另一個需要探索的集成機會是將分析和高級報告構建到你的 CI/CD 管道中。這有助於你利用通過管道傳輸的數據。",-1)),t[32]||(t[32]=i("h3",{id:"總結",tabindex:"-1"},[l("總結 "),i("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),t[33]||(t[33]=i("p",null,"CI/CD 管道是 DevOps 的基礎。開源使其能夠適應並靈活地滿足你在 DevOps 之旅中實施的運營變更所產生的新需求。",-1)),t[34]||(t[34]=i("p",null,"我希望看到對統一 DevOps 平台趨勢的開源響應，在這種趨勢中，組織尋求端到端的 CI/CD 解決方案。這種解決方案的要素就在那裏。畢竟，GitLab 和 GitHub 將他們的平台追溯到開源根源。",-1)),t[35]||(t[35]=i("p",null,"最後，不要忘記每一個成功的 CI/CD 工具鏈背後的教育和外展。記錄你的工具鏈和相關流程將改善開發人員入職和持續的 DevOps 團隊培訓。",-1)),t[36]||(t[36]=i("p",null,"你和你的組織如何定義你的 CI/CD 工具鏈？請在評論中分享你的反饋。",-1)),t[37]||(t[37]=i("hr",null,null,-1)),i("p",null,[t[14]||(t[14]=l("via: ",-1)),r(e,{href:"https://opensource.com/article/21/6/what-cicd-pipeline"},{default:s(()=>[...t[13]||(t[13]=[l("https://opensource.com/article/21/6/what-cicd-pipeline",-1)])]),_:1})]),i("p",null,[t[19]||(t[19]=l("作者：",-1)),r(e,{href:"https://opensource.com/users/willkelly"},{default:s(()=>[...t[15]||(t[15]=[l("Will Kelly",-1)])]),_:1}),t[20]||(t[20]=l(" 選題：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[16]||(t[16]=[l("lujun9972",-1)])]),_:1}),t[21]||(t[21]=l(" 譯者：",-1)),r(e,{href:"https://github.com/baddate"},{default:s(()=>[...t[17]||(t[17]=[l("baddate",-1)])]),_:1}),t[22]||(t[22]=l(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[18]||(t[18]=[l("wxy",-1)])]),_:1})]),i("p",null,[t[25]||(t[25]=l("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[23]||(t[23]=[l("LCTT",-1)])]),_:1}),t[26]||(t[26]=l(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:s(()=>[...t[24]||(t[24]=[l("Linux中國",-1)])]),_:1}),t[27]||(t[27]=l(" 榮譽推出",-1))])])}const v=o(a,[["render",d]]);export{S as __pageData,v as default};
